import test from "node:test";
import assert from "node:assert/strict";
import { lineOf, recordOf } from "../lib/injection.js";

const PINNED = [
	{ predicate: "name", object: "林舟", qualifier: "", source: "user", observed_at: "2026-11-23T01:02:03.000Z" },
	{ predicate: "allergy", object: "花生", qualifier: "轻度", source: "model", observed_at: "2026-11-24T04:05:06.000Z" },
];

test("recordOf keeps count and the fields the chip needs", () => {
	const record = recordOf({ sessionId: "s-1", turn: 2, step: 1, facts: PINNED, now: 1234 });
	assert.equal(record.v, 1);
	assert.equal(record.t, 1234);
	assert.equal(record.s, "s-1");
	assert.equal(record.turn, 2);
	assert.equal(record.step, 1);
	assert.equal(record.n, 2);
	assert.equal(record.removed, 0);
	assert.deepEqual(record.f[0], { p: "name", o: "林舟", q: "", src: "user", at: "2026-11-23T01:02:03.000Z" });
	assert.equal(record.f[1].q, "轻度");
});

test("recordOf marks a removal and carries no facts", () => {
	const record = recordOf({ sessionId: "s-2", turn: 1, step: 1, facts: [], removed: true, now: 9 });
	assert.equal(record.n, 0);
	assert.equal(record.removed, 1);
	assert.deepEqual(record.f, []);
});

test("recordOf needs a session id", () => {
	assert.equal(recordOf({ sessionId: "", facts: PINNED }), null);
	assert.equal(recordOf({ facts: PINNED }), null);
});

test("recordOf caps the fact list without dropping the count of the snapshot", () => {
	const many = Array.from({ length: 40 }, (_, index) => ({ predicate: "note", object: `v${index}` }));
	const record = recordOf({ sessionId: "s-3", facts: many, now: 1 });
	assert.equal(record.f.length, 30);
	assert.equal(record.n, 30);
});

test("lineOf is one newline-terminated JSON line", () => {
	const line = lineOf(recordOf({ sessionId: "s-4", facts: PINNED, now: 5 }));
	assert.equal(line.endsWith("\n"), true);
	assert.equal(line.indexOf("\n"), line.length - 1);
	assert.equal(JSON.parse(line).s, "s-4");
});
